"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["2576"],{67651(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>u,assets:()=>l});var n=JSON.parse('{"id":"qiangguo/applaudforjs","title":"","description":"At the third session of the Jiangsu Provincial 10th People\'s Congress held at the end of June this year, the Standing Committee of the current Jiangsu Provincial People\'s Congress revised and passed the new \\"Jiangsu Province Temporary Residents Management Regulations.\\" Notably, the previous clause \\"strictly prohibiting men and women without marriage certificates from cohabiting\\" was abolished. It is reported that when 50-plus members of the Standing Committee discussed in groups whether to abolish this clause, all expressed understanding and support. When it was finally put to a vote, it passed unanimously.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/applaudforjs.md","sourceDirName":"qiangguo","slug":"/qiangguo/applaudforjs","permalink":"/en/qiangguo/applaudforjs","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"applaudforjs","title":"","hide_table_of_contents":true,"sidebar_label":"Enthusiastic Applause for Jiangsu\'s Removal of the \\"Strictly Prohibiting Cohabitation of Men and Women Without Marriage Certificate\\" Regulation"},"sidebar":"qiangguoSidebar","previous":{"title":"\u4E9A\u6D32\u201C\u4E1C\u4EAC\u6E7E\u201D\u6218\u7565\u5C06\u5BF9\u53F0\u6E7E\u95EE\u9898\u7684\u6700\u7EC8\u5B8C\u6EE1\u89E3\u51B3\u8D77\u7740\u51B3\u5B9A\u6027\u7684\u4F5C\u7528\u3002","permalink":"/en/qiangguo/tokyobaystrategy"},"next":{"title":"Class Struggle Handbook 2: How Did \\"Class Struggle\\" Become the Left\'s Underwear!","permalink":"/en/qiangguo/classstrugglemanual"}}'),o=i(74848),a=i(28453);let s={id:"applaudforjs",title:"",hide_table_of_contents:!0,sidebar_label:'Enthusiastic Applause for Jiangsu\'s Removal of the "Strictly Prohibiting Cohabitation of Men and Women Without Marriage Certificate" Regulation'},r='A Thunderous Applause for Jiangsu\'s Abolition of the "Strict Prohibition on Unmarried Men and Women Cohabiting" Regulation',l={},u=[];function h(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"a-thunderous-applause-for-jiangsus-abolition-of-the-strict-prohibition-on-unmarried-men-and-women-cohabiting-regulation",children:'A Thunderous Applause for Jiangsu\'s Abolition of the "Strict Prohibition on Unmarried Men and Women Cohabiting" Regulation'})}),"\n",(0,o.jsx)(t.p,{children:'At the third session of the Jiangsu Provincial 10th People\'s Congress held at the end of June this year, the Standing Committee of the current Jiangsu Provincial People\'s Congress revised and passed the new "Jiangsu Province Temporary Residents Management Regulations." Notably, the previous clause "strictly prohibiting men and women without marriage certificates from cohabiting" was abolished. It is reported that when 50-plus members of the Standing Committee discussed in groups whether to abolish this clause, all expressed understanding and support. When it was finally put to a vote, it passed unanimously.'}),"\n",(0,o.jsx)(t.p,{children:"It turns out that this regulation, born of a specific historical period, has absolutely no legal basis in today's context. According to general principles of jurisprudence, behavior not prohibited by law should be considered permitted, and the government should not intervene. Furthermore, the scope of \"men and women without marriage certificates\" is very broad\u2014fathers and daughters, mothers and sons, brothers and sisters all fall into this category. When they go out, are they not allowed to share accommodations? This regulation was mainly intended to prevent prostitution, drug use, and other suspected illegal and criminal activities, but in practice it was extremely difficult to enforce. Moreover, logically, while some people may use mixed-gender cohabitation for prostitution or drug use, one cannot conclude that mixed-gender cohabitation necessarily constitutes prostitution or drug use, and therefore prohibit it. Besides, if it's drug use, can't same-sex individuals do it just as easily together? As for prostitution, can't same-sex individuals engage in prostitution? Does restricting opposite-sex cohabitation amount to encouraging same-sex activity?"}),"\n",(0,o.jsx)(t.p,{children:"Every adult has the right to exercise the rights granted by the Constitution, yet in the past, many regulations clearly contradicted the Constitution. This strict prohibition on unmarried men and women cohabiting clearly violated the spirit of the Constitution. Every citizen has the right to choose to live with anyone they feel is appropriate\u2014does this really need any explanation? Every person's every organ belongs to them personally. No person or institution has the right to restrict anyone from using their own organs, provided no harm is done to others\u2014is this really questionable? Any adult, on a voluntary basis, using their own organs to achieve corresponding physical and mental pleasure without affecting others\u2014is there really a problem with this?"}),"\n",(0,o.jsx)(t.p,{children:"The boundary between law and morality must be clearly defined. Law cannot replace morality, and vice versa. But in the past, we often had this tendency, where law ultimately became morality's accomplice, while truly illegal behavior was left unaddressed. If a country's laws are still obsessing over controlling its citizens' certain organs, it can only indicate serious immaturity. Jiangsu's abolition of the \"strict prohibition on unmarried men and women cohabiting\" regulation has set a good precedent, worthy of thunderous applause. Additionally, the abolition of this regulation directly cut off a revenue stream for certain corrupt police officers, indirectly accomplishing a great good deed. In short, Jiangsu's abolition of this regulation shows us a progressive trend in society, one that deserves strong advocacy."})]})}function d(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},28453(e,t,i){i.d(t,{R:()=>s,x:()=>r});var n=i(96540);let o={},a=n.createContext(o);function s(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);